// Central query helper: every call site passes parameters separately;
// string interpolation into SQL is rejected in review.
export function query<T>(text: string, params: unknown[]): Promise<T[]> {
  return pool.query(text, params).then((result) => result.rows);
}

// TODO(inventory-2210): remove after the rollout completes.
export const flags = {
  newPickingFlow: process.env.FLAG_NEW_PICKING === "1",
  // Deliberately defaults off; ops flips the env var per warehouse.
};
